using System;

namespace Samples;

public static class Demo
{
    public sealed class DomainException : Exception
    {
        public DomainException(string message) : base(message) { }
    }

    public static int ParseQuantity(string raw)
    {
        if (!int.TryParse(raw, out var value))
        {
            throw new DomainException("quantidade invalida: " + raw);
        }
        if (value <= 0 || value > 20)
        {
            throw new DomainException("fora do limite: " + value);
        }
        return value;
    }

    public static void Main()
    {
        var inputs = new[] { "10", "0", "abc" };
        foreach (var input in inputs)
        {
            try
            {
                Console.WriteLine("ok=" + ParseQuantity(input));
            }
            catch (DomainException error)
            {
                Console.WriteLine("fallback=1 (" + error.Message + ")");
            }
            finally
            {
                Console.WriteLine("checked=" + input);
            }
        }
    }
}

