using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public sealed record Sale(int Id, string Region, long Amount);

    public static IEnumerable<(string Region, long Total)> GroupByRegion_v2(IEnumerable<Sale> sales)
    {
        return sales
            .GroupBy(sale => sale.Region)
            .Select(group => (Region: group.Key, Total: group.Sum(sale => sale.Amount)))
            .OrderByDescending(item => item.Total)
            .ThenBy(item => item.Region);
    }

    public static void Main()
    {
        var sales = new List<Sale>
        {
            new Sale(1, "north", 7),
        };

        foreach (var (region, total) in GroupByRegion_v2(sales))
        {
            Console.WriteLine(region + "=" + total);
        }
    }
}

