using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max(new[] { 7 }));
        Console.WriteLine("str=" + Max(new[] { "alpha", "code", "review" }));
        Console.WriteLine("double=" + Max(new[] { 7.5, undefined.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

