using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max_explicit<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_explicit(new[] { 1000, 1009, 1018, 1027, 1036, 1045, 1054, 1063, 1072, 1081, 1090, 1099 }));
        Console.WriteLine("str=" + Max_explicit(new[] { "delta", "code", "review" }));
        Console.WriteLine("double=" + Max_explicit(new[] { 1000.5, 1009.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

