using System;
using System.Threading.Tasks;

namespace Samples;

public static class Demo
{
    private static async Task<int> TransformAsync(int value)
    {
        await Task.Yield();
        return value * 2 + 3;
    }

    public static async Task<int> ComputeAsync_safe(int baseValue)
    {
        var left = TransformAsync(baseValue + 7);
        var right = TransformAsync(baseValue - 4);
        var results = await Task.WhenAll(left, right);
        return results[0] + results[1];
    }

    public static async Task Main()
    {
        var result = await ComputeAsync_safe(6);
        Console.WriteLine("result=" + result);
    }
}

